select c.* from (SELECT a.id, a.cell, ROW_NUMBER() OVER (PARTITION BY cell ORDER BY id) AS row_num from b_wuba_colliding_data_front a left join b_wuba_colliding_data_rob b on a.cell = b.cell and b.create_time >= curdate() and b.create_time < date_add(curdate(), interval 1 day) where b.id is null and a.api_code = #{apiCode} and a.local_id = #{localId} and a.push_status = 1 and a.status = 1) as c where c.row_num = 1
and c.id > #{minId}
order by c.id limit #{pageSize};

